const messages = $('Start').first().json.messages_firstItem || [];
const attachments = [];
const vus = new Set();

const typesAutorises = [
  'application/pdf',
  'image/jpeg', 
  'image/png',
  'image/jpg',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
];

function extractAttachments(parts, messageId) {
  if (!parts) return;
  for (const part of parts) {
    if (part.body?.attachmentId && part.filename && typesAutorises.includes(part.mimeType)) {
      if (!vus.has(part.filename)) {
        vus.add(part.filename);
        attachments.push({
          messageId,
          attachmentId: part.body.attachmentId,
          filename: part.filename,
          mimeType: part.mimeType
        });
      }
    }
    if (part.parts) extractAttachments(part.parts, messageId);
  }
}

for (const msg of messages) {
  if (msg.payload?.parts) extractAttachments(msg.payload.parts, msg.id);
}

if (attachments.length === 0) return [{ json: { statut: 'aucune_piece_jointe' } }];
return attachments.map(att => ({ json: att }));

function getBody(payload) {
  if (!payload) return '';

  if (payload.body?.data) {
    return Buffer.from(payload.body.data, 'base64').toString('utf-8');
  }

  if (payload.parts) {
    for (const part of payload.parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        return Buffer.from(part.body.data, 'base64').toString('utf-8');
      }
    }
    for (const part of payload.parts) {
      const nested = getBody(part);
      if (nested) return nested;
    }
  }

  return '';
}

const messages = $('Start').first().json.messages_firstItem || [];
const texteEmails = messages.map(m => {
  const h = m.payload?.headers || [];
  const de = h.find(x => x.name === 'From')?.value || '';
  const sujet = h.find(x => x.name === 'Subject')?.value || '';
  const corps = getBody(m.payload) || m.snippet || '';
  return `De: ${de} | Objet: ${sujet}\n${corps}`;
}).join('\n---\n');

const items = $input.all();
const hashVus = new Set();
const fichiers = [];
const today = new Date().toISOString().split('T')[0];
const nomSociete = 'SOCIETE';

for (const item of items) {
  const hash = item.json.hash || '';
  if (!hash || hashVus.has(hash)) continue;
  hashVus.add(hash);

  fichiers.push({
    filename: `${today}_${nomSociete}_${item.json.filename || 'document'}`,
    filenameOriginal: item.json.filename || 'document',
    mimeType: item.json.mimeType || '',
    hash,
    texteOCR: item.json.text || item.json.texteOCR || '',
    messageId: item.json.messageId || '',
    attachmentId: item.json.attachmentId || '',
    malware: item.json.malware || false,
    statut: 'valide'
  });
}

const texteOCR = fichiers.map((f, i) =>
  `=== Fichier ${i+1} : ${f.filenameOriginal} ===\n${f.texteOCR}`
).join('\n\n');

const clientId = `CLI-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

return [{ json: { texteEmails, texteOCR, fichiers, clientId, today } }];

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {

  const base64Standard = items[i].json.data
    .replace(/-/g, '+')
    .replace(/_/g, '/');

  const pdfBuffer = Buffer.from(base64Standard, 'base64');

  results.push({
    json: items[i].json,
    binary: {
      data: await this.helpers.prepareBinaryData(
        pdfBuffer,
        items[i].json.filename || 'document.pdf',
        'application/pdf'
      )
    }
  });
}

return results;

const items = $input.all();
const originaux = $('JS-Extraire Pièces Jointes').all();
const hashVus = new Set();
const resultats = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const orig = originaux[i]?.json || {};

  const hash = item.hash || '';
  if (hashVus.has(hash)) continue;
  hashVus.add(hash);

  resultats.push({
    json: {
      filename: orig.filename || 'document',
      mimeType: orig.mimeType || '',
      hash,
      texteOCR: item.text || item.texteOCR || '',
      messageId: orig.messageId || '',
      attachmentId: orig.attachmentId || '',
      malware: item.malware || false,
      statut: 'valide'
    }
  });
}

if (resultats.length === 0) {
  return [{ json: { statut: 'aucun_fichier_valide' } }];
}
return resultats;

const raw = $json.output;
let parsed;
try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [{
    json: {
      ...$json,
      valide: false,
      champs_erreur: ['parsing_json'],
      details_erreurs: [{ champ: 'parsing_json', valeur: 'Impossible de parser la sortie de l\'agent' }]
    }
  }];
}

// Liste des champs essentiels à vérifier — les autres champs ne bloquent pas la validation
const champsAVerifier = ['id', 'nom_societe', 'email_client', 'parcours', 'paie', 'juridique'];

const valeursInvalides = ['erreur', 'non renseigné', 'non renseigne'];
const champsEnErreur = [];
const detailsErreurs = [];

for (const cle of champsAVerifier) {
  const valeur = parsed[cle];
  if (typeof valeur === 'string' && valeursInvalides.includes(valeur.trim().toLowerCase())) {
    champsEnErreur.push(cle);
    detailsErreurs.push({ champ: cle, valeur: valeur });
  }
}

const valide = champsEnErreur.length === 0;

return [{
  json: {
    ...parsed,
    valide,
    champs_erreur: champsEnErreur,
    details_erreurs: detailsErreurs,
    resume_erreurs: detailsErreurs.map(d => `${d.champ}: ${d.valeur}`).join(', ')
  }
}];
